    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); T=np.array(G['Test input']); th,tw=T.shape
# find shortest shifts (dv,dh) with high agreement over clean data, then fill 8-block by mode of candidates
noise=(T==8)
cells=[(i,j) for i in range(th) for j in range(tw) if not noise[i,j]]
best=None
for dv in range(1,15):
    for dh in range(-12,13):
        ok=0;tot=0
        for i,j in cells:
            ii=i-dv;jj=j-dh
            if 0<=ii<th and 0<=jj<tw and not noise[ii,jj]:
                tot+=1
                if T[i,j]==T[ii,jj]: ok+=1
        if tot and ok/tot>best[0]: best=(ok/tot,dv,dh)
print('best shift:',best)
dv,dh=best[1],best[2]
cands=[]
for i in range(14,23):
    for j in range(0,3):
        if noise[i,j]: continue
        cands.append(int(T[i,j]))
# fill 8-block: for each cell take candidates from congruent positions modulo shifts
res=T.copy(); res[14:23,0:3]=np.nan
for i in range(14,23):
    for j in range(0,3):
        vals=[int(T[i-dv,k]) for k in range(0,3) if 0<=k<3 and not noise[i-dv,k]]
        vals.extend([int(T[i,k-dh]) for k in range(0,3) if 0<=k<3 and not noise[i,k-dh]])
        # fallback use direct neighbor above within block if exists
        if vals: res[i,j]=np.ceil(vals[0]/8)? ...
print(res)
